/*
 * xns/test/test_idp_helpers.c - xns_$get_checksum (0x00E17D46) and
 * xns_$is_broadcast_addr (0x00E17E88), re-emitted from the disassembly
 * (source-tydd).
 *
 * Generated by: Claude Fable 5.1
 *
 * xns/idp_helpers.c is #included, with stubs for XNS_IDP_$CHECKSUM (which
 * records every call and answers from a script, so the partial sums are
 * visible), NETBUF_$GETVA / NETBUF_$RTNVA, and the MAC_OS / ROUTE symbols
 * the other helpers in that file name.  Everything the two functions reach
 * through a target VA (the IDP header, the descriptor chain, the port
 * network records, the payload page) lives in one arena that
 * ARCH_HOST_VA_BASE points ARCH_VA_TO_PTR at.
 *
 * Facts under test (the instruction that fixes each is cited in
 * xns/idp_helpers.c):
 *   get_checksum
 *     - header only: (length - 1) / 2 words from the header's length word;
 *     - the IDP length must cover every buffer ("idp length + 1 < bytes so
 *       far" is -1), including a negative length word;
 *     - the header chain is walked to next == 0, (length + 1) / 2 words each,
 *       the word sums added with 16-bit wrap;
 *     - payload pages: (chunk + 1) / 2 words, at most 0x400 bytes a page,
 *       NETBUF_$GETVA always given data_pages[0], one NETBUF_$RTNVA per page;
 *     - a page with nothing left returns the LAST partial sum, not the total
 *       (the 0x00E17E10 / 0x00E17E16 exits skip "move.w D4w,D0w"), so every
 *       packet with a payload shorter than four pages - every IDP packet -
 *       yields its last page's partial; only a payload-less packet or one
 *       filling all four pages returns the total;
 *     - a missing page with bytes left, or a NETBUF_$GETVA failure, is -1.
 *   is_broadcast_addr
 *     - the all-ones host is true before any table is read;
 *     - true needs a port whose network record matches AND a registered
 *       host among entries 0..registered_count;
 *     - a negative registered_count skips the address table;
 *     - all eight ports are searched, and the three host words are compared
 *       as words.
 */

#include <stdio.h>
#include <stdint.h>
#include <string.h>

#include "xns/xns_internal.h"

static int tests_failed = 0;
static int tests_passed = 0;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name) do { \
    int _before = tests_failed; \
    printf("  Running %s... ", #name); \
    fflush(stdout); \
    reset_stubs(); \
    test_##name(); \
    if (tests_failed == _before) { \
        tests_passed++; \
        printf("PASSED\n"); \
    } \
} while (0)

#define ASSERT_EQ(a, b) do { \
    unsigned long _a = (unsigned long)(a); \
    unsigned long _b = (unsigned long)(b); \
    if (_a != _b) { \
        printf("FAILED\n    %s = 0x%lx (%lu), %s = 0x%lx (%lu) at line %d\n", \
               #a, _a, _a, #b, _b, _b, __LINE__); \
        tests_failed++; \
        return; \
    } \
} while (0)

