#include "../xns_data.c"

route_$port_t  ROUTE_$PORT_ARRAY[ROUTE_$MAX_PORTS];
route_$port_t *ROUTE_$PORTP[ROUTE_$MAX_PORTS];

void MAC_OS_$OPEN(int16_t *port_num, mac_os_$open_params_t *params,
                  status_$t *status_ret)
{
    (void)port_num; (void)params;
    *status_ret = status_$ok;
}

void MAC_OS_$CLOSE(int16_t *channel, status_$t *status_ret)
{
    (void)channel;
    *status_ret = status_$ok;
}

void XNS_IDP_$OS_DEMUX(xns_$mac_rcv_t *pkt, int16_t *port_ptr,
                       boolean *mac_broadcast, status_$t *status_ret)
{
    (void)pkt; (void)port_ptr; (void)mac_broadcast; (void)status_ret;
}

/* The arena every target VA resolves into; VA 0 stays NULL, so nothing is
 * placed at its start. */
static uint8_t arena[0x2000];
#define VA(p) ((uint32_t)((const uint8_t *)(p) - arena))

/* XNS_IDP_$CHECKSUM: record (data, words) and answer from a script */
#define MAX_CALLS 8
static int       csum_calls;
static uint16_t *csum_data[MAX_CALLS];
static int16_t   csum_words[MAX_CALLS];
static uint16_t  csum_answer[MAX_CALLS];

uint16_t XNS_IDP_$CHECKSUM(uint16_t *data, int16_t word_count)
{
    int n = csum_calls++;
    if (n < MAX_CALLS) {
        csum_data[n] = data;
        csum_words[n] = word_count;
        return csum_answer[n];
    }
    return 0;
}

/* NETBUF_$GETVA / NETBUF_$RTNVA: one payload page in the arena */
static int       getva_calls;
static uint32_t  getva_arg[MAX_CALLS];
static status_$t getva_status;
static uint8_t  *page_ptr;
static int       rtnva_calls;
static uint32_t  rtnva_arg[MAX_CALLS];

void NETBUF_$GETVA(uint32_t ppn_shifted, uint32_t *va_out, status_$t *status)
{
    int n = getva_calls++;
    if (n < MAX_CALLS) {
        getva_arg[n] = ppn_shifted;
    }
    *va_out = VA(page_ptr);
    *status = getva_status;
}

uint32_t NETBUF_$RTNVA(uint32_t *va_ptr)
{
    int n = rtnva_calls++;
    if (n < MAX_CALLS) {
        rtnva_arg[n] = *va_ptr;
    }
    return 0;
}

static void reset_stubs(void)
{
    memset(arena, 0, sizeof(arena));
    memset(&XNS_IDP_$DATA, 0, sizeof(XNS_IDP_$DATA));
    csum_calls = 0;
    memset(csum_data, 0, sizeof(csum_data));
    memset(csum_words, 0, sizeof(csum_words));
    memset(csum_answer, 0, sizeof(csum_answer));
    getva_calls = 0;
    getva_status = status_$ok;
    rtnva_calls = 0;
    page_ptr = arena + 0x1000;
}

#include "../idp_helpers.c"

/* ============================================================================
 * xns_$get_checksum
 * ============================================================================ */

/* Arena layout for the checksum tests */
#define REC_OFF     0x0100
#define HDR_OFF     0x0200
#define ELEM_OFF    0x0300
#define ELEM2_OFF   0x0320
#define BUF_OFF     0x0400

static mac_os_$send_pkt_t *make_rec(uint16_t idp_length, int32_t hdr_bytes)
{
    mac_os_$send_pkt_t *rec = (mac_os_$send_pkt_t *)(arena + REC_OFF);
    xns_$idp_header_t  *hdr = (xns_$idp_header_t *)(arena + HDR_OFF);

    memset(rec, 0, sizeof(*rec));
    hdr->length = idp_length;
    rec->hdr_desc.length  = hdr_bytes;
    rec->hdr_desc.address = VA(hdr);
    rec->hdr_desc.next    = 0;
    return rec;
}

TEST(checksum_header_only_sums_from_the_length_word)
{
    mac_os_$send_pkt_t *rec = make_rec(30, 30);

    csum_answer[0] = 0x1234;
    ASSERT_EQ(xns_$get_checksum(rec), 0x1234);
    ASSERT_EQ(csum_calls, 1);
    /* "lea (0x2,A3),A0": the header's length word onward */
    ASSERT_EQ((uintptr_t)csum_data[0], (uintptr_t)(arena + HDR_OFF + 2));
    /* (30 - 1) / 2 = 14 words */
    ASSERT_EQ(csum_words[0], 14);
    ASSERT_EQ(getva_calls, 0);
    ASSERT_EQ(rtnva_calls, 0);
}

TEST(checksum_header_longer_than_idp_length_is_minus_one)
{
    /* 10 + 1 < 30 */
    mac_os_$send_pkt_t *rec = make_rec(10, 30);

    ASSERT_EQ((int16_t)xns_$get_checksum(rec), -1);
    ASSERT_EQ(csum_calls, 0);
}

TEST(checksum_negative_idp_length_is_minus_one)
{
    /* 0xFFFF sign-extends to -1: -1 + 1 = 0 < 30 */
    mac_os_$send_pkt_t *rec = make_rec(0xFFFF, 30);

    ASSERT_EQ((int16_t)xns_$get_checksum(rec), -1);
    ASSERT_EQ(csum_calls, 0);
}

TEST(checksum_walks_the_header_chain_to_next_zero)
{
    mac_os_$send_pkt_t *rec = make_rec(40, 30);
    mac_os_$buf_desc_t *e1 = (mac_os_$buf_desc_t *)(arena + ELEM_OFF);
    mac_os_$buf_desc_t *e2 = (mac_os_$buf_desc_t *)(arena + ELEM2_OFF);

    rec->hdr_desc.next = VA(e1);
    e1->length = 6;                     /* (6 + 1) / 2 = 3 words */
    e1->address = VA(arena + BUF_OFF);
    e1->next = VA(e2);
    e2->length = 3;                     /* (3 + 1) / 2 = 2 words */
    e2->address = VA(arena + BUF_OFF + 0x10);
    e2->next = 0;

    csum_answer[0] = 0xF000;
    csum_answer[1] = 0x1000;            /* 0xF000 + 0x1000 wraps to 0 */
    csum_answer[2] = 0x0007;
    ASSERT_EQ(xns_$get_checksum(rec), 0x0007);
    ASSERT_EQ(csum_calls, 3);
    ASSERT_EQ((uintptr_t)csum_data[1], (uintptr_t)(arena + BUF_OFF));
    ASSERT_EQ(csum_words[1], 3);
    ASSERT_EQ((uintptr_t)csum_data[2], (uintptr_t)(arena + BUF_OFF + 0x10));
    ASSERT_EQ(csum_words[2], 2);
}

TEST(checksum_chain_element_past_idp_length_is_minus_one)
{
    /* 30 + 6 = 36 > 34 + 1 */
    mac_os_$send_pkt_t *rec = make_rec(34, 30);
    mac_os_$buf_desc_t *e1 = (mac_os_$buf_desc_t *)(arena + ELEM_OFF);

    rec->hdr_desc.next = VA(e1);
    e1->length = 6;
    e1->address = VA(arena + BUF_OFF);
    e1->next = 0;

    ASSERT_EQ((int16_t)xns_$get_checksum(rec), -1);
    ASSERT_EQ(csum_calls, 1);           /* the header was summed first */
}

TEST(checksum_one_payload_page)
{
    mac_os_$send_pkt_t *rec = make_rec(46, 30);

    rec->data_length = 0x10;            /* (0x10 + 1) / 2 = 8 words */
    rec->data_pages[0] = 0x00012345;
    csum_answer[0] = 0x0100;
    csum_answer[1] = 0x0023;
    /* page 2 has 0x10 - 0x400 < 0 bytes left: 0x00E17E10 returns D0, the
     * page-1 partial, and the header's 0x0100 is dropped */
    ASSERT_EQ(xns_$get_checksum(rec), 0x0023);
    ASSERT_EQ(csum_calls, 2);
    ASSERT_EQ(getva_calls, 1);
    ASSERT_EQ(getva_arg[0], 0x00012345);
    ASSERT_EQ((uintptr_t)csum_data[1], (uintptr_t)page_ptr);
    ASSERT_EQ(csum_words[1], 8);
    ASSERT_EQ(rtnva_calls, 1);
    ASSERT_EQ(rtnva_arg[0], VA(page_ptr));
}

TEST(checksum_odd_payload_rounds_up_to_words)
{
    mac_os_$send_pkt_t *rec = make_rec(46, 30);

    rec->data_length = 0x0F;            /* (0x0F + 1) / 2 = 8 words */
    rec->data_pages[0] = 0x00012345;
    csum_answer[0] = 1;
    csum_answer[1] = 2;
    ASSERT_EQ(xns_$get_checksum(rec), 2);        /* the page partial again */
    ASSERT_EQ(csum_words[1], 8);
}

TEST(checksum_payload_past_idp_length_is_minus_one)
{
    /* 30 + 0x10 = 46 > 30 + 1 */
    mac_os_$send_pkt_t *rec = make_rec(30, 30);

    rec->data_length = 0x10;
    rec->data_pages[0] = 0x00012345;
    ASSERT_EQ((int16_t)xns_$get_checksum(rec), -1);
    ASSERT_EQ(getva_calls, 0);
}

TEST(checksum_missing_page_with_bytes_left_is_minus_one)
{
    mac_os_$send_pkt_t *rec = make_rec(46, 30);

    rec->data_length = 0x10;
    rec->data_pages[0] = 0;             /* "tst.l (0x38,A4)" is zero */
    ASSERT_EQ((int16_t)xns_$get_checksum(rec), -1);
    ASSERT_EQ(getva_calls, 0);
}

TEST(checksum_getva_failure_is_minus_one)
{
    mac_os_$send_pkt_t *rec = make_rec(46, 30);

    rec->data_length = 0x10;
    rec->data_pages[0] = 0x00012345;
    getva_status = 0x00120001;
    ASSERT_EQ((int16_t)xns_$get_checksum(rec), -1);
    ASSERT_EQ(csum_calls, 1);
    ASSERT_EQ(rtnva_calls, 0);
}

TEST(checksum_page_with_nothing_left_returns_the_last_partial_sum)
{
    /* 0x400 bytes of payload: page 1 takes all of it, page 2 has exactly
     * nothing left, and 0x00E17E10 / 0x00E17E16 leave D0 = the page-1
     * partial */
    mac_os_$send_pkt_t *rec = make_rec(0x41E, 30);

    rec->data_length = 0x400;
    rec->data_pages[0] = 0x00012345;
    rec->data_pages[1] = 0;
    csum_answer[0] = 0x1111;
    csum_answer[1] = 0x2222;
    ASSERT_EQ(xns_$get_checksum(rec), 0x2222);   /* not 0x3333 */
    ASSERT_EQ(csum_calls, 2);
    ASSERT_EQ(csum_words[1], 0x200);
    ASSERT_EQ(getva_calls, 1);
    ASSERT_EQ(rtnva_calls, 1);

    /* the same with the second page present: the exit at 0x00E17E16 */
    reset_stubs();
    rec = make_rec(0x41E, 30);
    rec->data_length = 0x400;
    rec->data_pages[0] = 0x00012345;
    rec->data_pages[1] = 0x00023456;
    csum_answer[0] = 0x1111;
    csum_answer[1] = 0x2222;
    ASSERT_EQ(xns_$get_checksum(rec), 0x2222);
    ASSERT_EQ(getva_calls, 1);
}

TEST(checksum_second_page_is_mapped_from_data_pages_0)
{
    mac_os_$send_pkt_t *rec = make_rec(0x51E, 30);

    rec->data_length = 0x500;           /* 0x400 then 0x100 bytes */
    rec->data_pages[0] = 0x00012345;
    rec->data_pages[1] = 0x00023456;
    csum_answer[0] = 0x0001;
    csum_answer[1] = 0x0010;
    csum_answer[2] = 0x0100;
    /* page 3 has nothing left: the page-2 partial comes back */
    ASSERT_EQ(xns_$get_checksum(rec), 0x0100);
    ASSERT_EQ(csum_calls, 3);
    ASSERT_EQ(csum_words[1], 0x200);
    ASSERT_EQ(csum_words[2], 0x80);
    ASSERT_EQ(getva_calls, 2);
    /* "move.l (0x3c,A2),-(SP)" both times */
    ASSERT_EQ(getva_arg[0], 0x00012345);
    ASSERT_EQ(getva_arg[1], 0x00012345);
    ASSERT_EQ(rtnva_calls, 2);
}

TEST(checksum_four_full_pages_return_the_total)
{
    /* the dbf at 0x00E17E78 ends the loop: 0x00E17E7C copies D4 to D0 */
    mac_os_$send_pkt_t *rec = make_rec(0x101E, 30);

    rec->data_length = 0x1000;
    rec->data_pages[0] = 0x00012345;
    rec->data_pages[1] = 0x00023456;
    rec->data_pages[2] = 0x00034567;
    rec->data_pages[3] = 0x00045678;
    csum_answer[0] = 1;
    csum_answer[1] = 2;
    csum_answer[2] = 4;
    csum_answer[3] = 8;
    csum_answer[4] = 16;
    ASSERT_EQ(xns_$get_checksum(rec), 31);
    ASSERT_EQ(csum_calls, 5);
    ASSERT_EQ(csum_words[4], 0x200);
    ASSERT_EQ(getva_calls, 4);
    ASSERT_EQ(getva_arg[3], 0x00012345);
    ASSERT_EQ(rtnva_calls, 4);
}

/* ============================================================================
 * xns_$is_broadcast_addr
 * ============================================================================ */

#define PORTNET_OFF 0x0800

/* Every port's network record in the arena, port p's network = net[p] */
static void set_port_networks(const uint32_t *net)
{
    int p;
    for (p = 0; p < XNS_MAX_PORTS; p++) {
        uint32_t *cell = (uint32_t *)(arena + PORTNET_OFF + p * 4);
        *cell = net[p];
        XNS_IDP_$DATA.ports[p].net_addr_ptr = VA(cell);
    }
}

static void set_addr(uint8_t *a, uint32_t network, uint16_t h0, uint16_t h1,
                     uint16_t h2)
{
    memcpy(a, &network, 4);
    memcpy(a + 4, &h0, 2);
    memcpy(a + 6, &h1, 2);
    memcpy(a + 8, &h2, 2);
    memset(a + 10, 0, 2);
}

TEST(broadcast_all_ones_host_is_true_before_any_table)
{
    uint8_t a[12];

    /* no port record is valid: a table read would dereference NULL */
    set_addr(a, 0x00000005, 0xFFFF, 0xFFFF, 0xFFFF);
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), -1);
}

TEST(broadcast_registered_host_on_a_port_network_is_true)
{
    static const uint32_t nets[8] = { 1, 2, 3, 0x1234, 5, 6, 7, 8 };
    uint8_t a[12];

    set_port_networks(nets);
    XNS_IDP_$DATA.registered_count = 1;
    XNS_IDP_$DATA.addrs[0][0] = 0x0800; XNS_IDP_$DATA.addrs[0][1] = 0x1E01; XNS_IDP_$DATA.addrs[0][2] = 0x0002;
    XNS_IDP_$DATA.addrs[1][0] = 0x0800; XNS_IDP_$DATA.addrs[1][1] = 0x1E03; XNS_IDP_$DATA.addrs[1][2] = 0x0004;

    set_addr(a, 0x1234, 0x0800, 0x1E03, 0x0004);
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), -1);
    set_addr(a, 0x1234, 0x0800, 0x1E01, 0x0002);
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), -1);
}

TEST(broadcast_unregistered_host_is_false)
{
    static const uint32_t nets[8] = { 1, 2, 3, 0x1234, 5, 6, 7, 8 };
    uint8_t a[12];

    set_port_networks(nets);
    XNS_IDP_$DATA.registered_count = 0;
    XNS_IDP_$DATA.addrs[0][0] = 0x0800; XNS_IDP_$DATA.addrs[0][1] = 0x1E01; XNS_IDP_$DATA.addrs[0][2] = 0x0002;

    /* each host word differs on its own: the compares are word compares */
    set_addr(a, 0x1234, 0x0801, 0x1E01, 0x0002);
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), 0);
    set_addr(a, 0x1234, 0x0800, 0x1E00, 0x0002);
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), 0);
    set_addr(a, 0x1234, 0x0800, 0x1E01, 0x0003);
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), 0);
}

TEST(broadcast_entries_past_registered_count_are_ignored)
{
    static const uint32_t nets[8] = { 1, 2, 3, 0x1234, 5, 6, 7, 8 };
    uint8_t a[12];

    set_port_networks(nets);
    XNS_IDP_$DATA.registered_count = 0;         /* entry 0 only */
    XNS_IDP_$DATA.addrs[1][0] = 0x0800; XNS_IDP_$DATA.addrs[1][1] = 0x1E03; XNS_IDP_$DATA.addrs[1][2] = 0x0004;

    set_addr(a, 0x1234, 0x0800, 0x1E03, 0x0004);
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), 0);
    XNS_IDP_$DATA.registered_count = 1;         /* now entry 1 counts */
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), -1);
}

TEST(broadcast_negative_registered_count_skips_the_table)
{
    static const uint32_t nets[8] = { 1, 2, 3, 0x1234, 5, 6, 7, 8 };
    uint8_t a[12];

    set_port_networks(nets);
    XNS_IDP_$DATA.registered_count = -1;        /* "bmi" at 0x00E17EC0 */
    XNS_IDP_$DATA.addrs[0][0] = 0x0800; XNS_IDP_$DATA.addrs[0][1] = 0x1E01; XNS_IDP_$DATA.addrs[0][2] = 0x0002;

    set_addr(a, 0x1234, 0x0800, 0x1E01, 0x0002);
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), 0);
}

TEST(broadcast_network_on_no_port_is_false)
{
    static const uint32_t nets[8] = { 1, 2, 3, 4, 5, 6, 7, 8 };
    uint8_t a[12];

    set_port_networks(nets);
    XNS_IDP_$DATA.registered_count = 0;
    XNS_IDP_$DATA.addrs[0][0] = 0x0800; XNS_IDP_$DATA.addrs[0][1] = 0x1E01; XNS_IDP_$DATA.addrs[0][2] = 0x0002;

    set_addr(a, 0x1234, 0x0800, 0x1E01, 0x0002);
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), 0);
}

TEST(broadcast_all_eight_ports_are_searched)
{
    static const uint32_t nets[8] = { 1, 2, 3, 4, 5, 6, 7, 0x1234 };
    uint8_t a[12];

    set_port_networks(nets);
    XNS_IDP_$DATA.registered_count = 0;
    XNS_IDP_$DATA.addrs[0][0] = 0x0800; XNS_IDP_$DATA.addrs[0][1] = 0x1E01; XNS_IDP_$DATA.addrs[0][2] = 0x0002;

    set_addr(a, 0x1234, 0x0800, 0x1E01, 0x0002);
    ASSERT_EQ((int8_t)xns_$is_broadcast_addr(a), -1);
}

int main(void)
{
    ARCH_HOST_VA_BASE = (uintptr_t)arena;

    printf("xns_$get_checksum (0x00E17D46)\n");
    RUN_TEST(checksum_header_only_sums_from_the_length_word);
    RUN_TEST(checksum_header_longer_than_idp_length_is_minus_one);
    RUN_TEST(checksum_negative_idp_length_is_minus_one);
    RUN_TEST(checksum_walks_the_header_chain_to_next_zero);
    RUN_TEST(checksum_chain_element_past_idp_length_is_minus_one);
    RUN_TEST(checksum_one_payload_page);
    RUN_TEST(checksum_odd_payload_rounds_up_to_words);
    RUN_TEST(checksum_payload_past_idp_length_is_minus_one);
    RUN_TEST(checksum_missing_page_with_bytes_left_is_minus_one);
    RUN_TEST(checksum_getva_failure_is_minus_one);
    RUN_TEST(checksum_page_with_nothing_left_returns_the_last_partial_sum);
    RUN_TEST(checksum_second_page_is_mapped_from_data_pages_0);
    RUN_TEST(checksum_four_full_pages_return_the_total);

    printf("xns_$is_broadcast_addr (0x00E17E88)\n");
    RUN_TEST(broadcast_all_ones_host_is_true_before_any_table);
    RUN_TEST(broadcast_registered_host_on_a_port_network_is_true);
    RUN_TEST(broadcast_unregistered_host_is_false);
    RUN_TEST(broadcast_entries_past_registered_count_are_ignored);
    RUN_TEST(broadcast_negative_registered_count_skips_the_table);
    RUN_TEST(broadcast_network_on_no_port_is_false);
    RUN_TEST(broadcast_all_eight_ports_are_searched);

    printf("\n%d passed, %d failed\n", tests_passed, tests_failed);
    return tests_failed ? 1 : 0;
}
